// 原经济收据纯读组件，只证精确原因和相位；不冒共同市场保护/全世界冷重放已经启用。
#include "resident/domains/local_economy/market_history/economic_market_cause.hpp"
#include "resident/domains/local_economy/takeover/execution_receipts.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;void check(bool ok,const char* msg){++checks;if(!ok)throw std::runtime_error(msg);}
StableId fact(CommonStore& c,const StableId& prefix){auto id=c.next_id(prefix);check(id.ok,"actual source ID");check(c.append_fact({id.value,prefix,"local_economy"}).ok,"actual source header");return id.value;}
void sources(){auto cc=std::make_shared<CommonCatalog>();cc->items.insert("grain",{"grain",1,10});Owner owner{Owner::Kind::organization,"market.org",{}};cc->required_inventories.insert("stock",{owner,200});CommonStore c{CommonState{},cc};c.state().inventories.insert("stock",{"stock",owner,200,0,{}});LocalEconomyCatalog catalog;catalog.enabled=true;LocalEconomyState state;ProductionUnit unit;unit.id="unit";unit.owner=owner;unit.recipe_id="recipe";unit.output_inventory_id="stock";catalog.production_units.insert(unit.id,unit);state.production_units.insert(unit.id,unit);ProductionRecipe recipe;recipe.id="recipe";catalog.recipes.insert(recipe.id,recipe);auto id=fact(c,"local_production");ProductionReceipt p;p.id=id;p.unit_id=unit.id;p.recipe_id=recipe.id;p.tick=p.due_tick=1;p.inputs.push_back({"stock","grain",2});p.outputs.push_back({"stock","grain",3});p.unrealized_output.push_back({"stock","grain",9});state.production_receipts.insert(id,p);check(!read_economic_market_cause(c,*cc,state,catalog,id).ok,"cold does not borrow future receipt");DynamicStepInput phase{0,1};auto source=read_economic_market_cause(c,*cc,state,catalog,id,nullptr,&phase);check(source.ok&&source.value.source_tick==1&&source.value.legs.size()==2&&source.value.legs[0].signed_quantity==-2&&source.value.legs[1].signed_quantity==3,"phase exact consumed then produced legs without unrealized output");check(source.value.original_business_key==unit.id&&source.value.business_due_tick==p.due_tick,"scope original production key and due");check(owner_equal(source.value.legs[0].owner,owner),"original unit owner");DynamicStepInput bad{0,2};check(!read_economic_market_cause(c,*cc,state,catalog,id,nullptr,&bad).ok,"phase jump rejects");EconomicTakeoverExecutionState taken;taken.production.insert(id,{id,{}});check(!read_economic_market_cause(c,*cc,state,catalog,id,&taken,&phase).ok,"taken source unsupported rather than borrowing original owner");state.production_receipts.find(id)->inputs[0].quantity=-1;check(!read_economic_market_cause(c,*cc,state,catalog,id,nullptr,&phase).ok,"negative actual source rejects");state.production_receipts.find(id)->inputs[0].quantity=2;
 RecurringObligation obligation;obligation.id="ration";obligation.kind=ObligationKind::ration;obligation.principal={SubjectKind::organization,"market.org"};obligation.beneficiary={SubjectKind::cohort,"people"};obligation.source_wallet_or_inventory="stock";obligation.item_id="grain";catalog.obligations.insert(obligation.id,obligation);state.obligations.insert(obligation.id,obligation);auto ration=fact(c,"local_ration");state.rations.insert(ration,{ration,obligation.id,"stock","grain",obligation.beneficiary,1,1,5,0,5});auto zero=read_economic_market_cause(c,*cc,state,catalog,ration,nullptr,&phase);check(zero.ok&&zero.value.legs.empty(),"zero real consumption produces no fictitious leg");state.rations.find(ration)->consumed=3;state.rations.find(ration)->shortage=2;check(zero.value.original_business_key==obligation.id&&zero.value.business_due_tick==1,"scope original ration key and due even for zero consumption");auto used=read_economic_market_cause(c,*cc,state,catalog,ration,nullptr,&phase);check(used.ok&&used.value.legs.size()==1&&used.value.legs[0].signed_quantity==-3,"only actual ration consumption");auto ids=read_economic_market_cause_ids(c,*cc,state,catalog,{"stock"},nullptr,&phase);check(ids.ok&&ids.value==std::vector<StableId>{id,ration},"all nonzero original causes in real Common order");check(!read_economic_market_cause_ids(c,*cc,state,catalog,{"stock","stock"},nullptr,&phase).ok,"duplicate protected container rejects");state.rations.find(ration)->consumed=0;state.rations.find(ration)->shortage=5;ids=read_economic_market_cause_ids(c,*cc,state,catalog,{"stock"},nullptr,&phase);check(ids.ok&&ids.value==std::vector<StableId>{id},"zero consumption omitted from reverse requirement");state.rations.find(ration)->consumed=3;state.rations.find(ration)->shortage=2;auto header=*c.state().facts.find(ration);c.state().facts.erase(ration);check(!read_economic_market_cause_ids(c,*cc,state,catalog,{"stock"},nullptr,&phase).ok,"missing original header cannot hide receipt");c.state().facts.insert(ration,header);c.state().facts.find(ration)->domain="growth";check(!read_economic_market_cause(c,*cc,state,catalog,ration,nullptr,&phase).ok,"foreign header rejects");}
}
int main(){try{sources();std::cout<<checks<<"/0 economic market cause checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
